// Definition of a Binary Tree Node 
struct Node { 
    int data; 
    struct Node* left; 
    struct Node* right; 
}; 

// Function to create a new node 
struct Node* createNode(int value) { 
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node)); 
    newNode->data = value; 
    newNode->left = NULL; 
    newNode->right = NULL; 
    return newNode; 
} 

